python3 - <<'PY'
import os, zipfile, math
import openpyxl
from openpyxl.utils import get_column_letter
import xml.etree.ElementTree as ET

in_path='/root/data/workbook.xlsx'
out_path='/root/output/result.xlsx'

# load workbook with formulas already saved? We'll re-load from out_path to keep formulas.
wb=openpyxl.load_workbook(out_path, data_only=False)
ws_task=wb['Task']
ws_data=wb['Data']

# determine years (Task row 10 H-L)
years=[ws_task.cell(row=10,column=c).value for c in range(8,13)]
col_letters=[get_column_letter(c) for c in range(8,13)]
col_to_year=dict(zip(col_letters, years))

# find Data header row containing years (expect row 4)
header_row=None
header_cols=None
for r in range(1,51):
    row=[ws_data.cell(row=r,column=c).value for c in range(1,30)]
    if all(y in row for y in years):
        cols=[]
        for c in range(1,30):
            if ws_data.cell(row=r,column=c).value in years:
                cols.append(c)
        if len(cols)==len(years):
            header_row=r
            header_cols=cols
            break
if header_row is None:
    raise RuntimeError('Could not locate Data year header row')

# build lookup dict from Data rows 21-38
series_to_year_value={}
for r in range(21,39):
    code=ws_data.cell(row=r,column=4).value
    if not code:
        continue
    for idx,y in enumerate(years):
        c=header_cols[idx]
        series_to_year_value[(code,y)]=ws_data.cell(row=r,column=c).value

# compute cached numeric values for target cells
row_blocks=[(12,17),(19,24),(26,31)]

import math

def percentile_inc(sorted_vals, k):
    n=len(sorted_vals)
    if n==0:
        return None
    if k<=0:
        return sorted_vals[0]
    if k>=1:
        return sorted_vals[-1]
    pos=(n-1)*k + 1
    f=math.floor(pos)
    d=pos-f
    if d==0:
        return sorted_vals[f-1]
    return sorted_vals[f-1] + d*(sorted_vals[f]-sorted_vals[f-1])

computed={}
# block lookups
for r0,r1 in row_blocks:
    for r in range(r0,r1+1):
        code=ws_task[f'D{r}'].value
        for col in col_letters:
            y=col_to_year[col]
            computed[f'{col}{r}']=series_to_year_value.get((code,y))

# slack
for i in range(6):
    fin_r=12+i
    scrap_r=19+i
    cap_r=26+i
    slack_r=35+i
    for col in col_letters:
        fin=computed[f'{col}{fin_r}']
        scrap=computed[f'{col}{scrap_r}']
        cap=computed[f'{col}{cap_r}']
        if fin is None or scrap is None or cap in (None,0):
            val=None
        else:
            val=(fin-scrap)/cap*100
        computed[f'{col}{slack_r}']=val

# stats
for col in col_letters:
    vals=[computed[f'{col}{r}'] for r in range(35,41)]
    vals=[v for v in vals if v is not None]
    s=sorted(vals)
    if not s:
        minv=maxv=med=avg=p25=p75=None
    else:
        minv=s[0]; maxv=s[-1]
        n=len(s)
        med=s[n//2] if n%2==1 else (s[n//2-1]+s[n//2])/2
        avg=sum(s)/n
        p25=percentile_inc(s,0.25)
        p75=percentile_inc(s,0.75)
    computed[f'{col}42']=minv
    computed[f'{col}43']=maxv
    computed[f'{col}44']=med
    computed[f'{col}45']=avg
    computed[f'{col}46']=p25
    computed[f'{col}47']=p75

# weighted mean
for col in col_letters:
    slack=[computed[f'{col}{r}'] for r in range(35,41)]
    w=[computed[f'{col}{r}'] for r in range(26,32)]
    if any(v is None for v in slack) or any(v is None for v in w) or sum(w)==0:
        wm=None
    else:
        wm=sum(s*wt for s,wt in zip(slack,w))/sum(w)
    computed[f'{col}50']=wm

# patch xml cached values

def fmt_number(v):
    if v is None:
        return None
    if isinstance(v,bool):
        return '1' if v else '0'
    if isinstance(v,int):
        return str(v)
    if isinstance(v,float):
        if math.isnan(v) or math.isinf(v):
            return None
        return format(v,'.15g')
    return str(v)

with zipfile.ZipFile(out_path,'r') as z:
    workbook_xml=z.read('xl/workbook.xml')
    rels_xml=z.read('xl/_rels/workbook.xml.rels')

ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
wb_tree=ET.fromstring(workbook_xml)
rels_tree=ET.fromstring(rels_xml)

sheet_rid=None
for sh in wb_tree.find('m:sheets',ns).findall('m:sheet',ns):
    if sh.attrib.get('name')=='Task':
        sheet_rid=sh.attrib.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        break

rels_ns='{http://schemas.openxmlformats.org/package/2006/relationships}'
sheet_target=None
for rel in rels_tree.findall(f'{rels_ns}Relationship'):
    if rel.attrib.get('Id')==sheet_rid:
        sheet_target=rel.attrib.get('Target')
        break
if not sheet_target:
    raise RuntimeError('No target for Task sheet')

sheet_target=sheet_target.lstrip('/')
if sheet_target.startswith('xl/'):
    sheet_path=sheet_target
else:
    sheet_path='xl/'+sheet_target

with zipfile.ZipFile(out_path,'r') as z:
    sheet_xml=z.read(sheet_path)

sheet_ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'
ET.register_namespace('', sheet_ns)
root=ET.fromstring(sheet_xml)
sheetData=root.find(f'{{{sheet_ns}}}sheetData')
rows_by_r={}
for row_el in sheetData.findall(f'{{{sheet_ns}}}row'):
    rr=row_el.attrib.get('r')
    if rr:
        rows_by_r[int(rr)]=row_el

def find_cell(row_el, coord):
    for c in row_el.findall(f'{{{sheet_ns}}}c'):
        if c.attrib.get('r')==coord:
            return c
    return None

patched=0
for coord,val in computed.items():
    vtxt=fmt_number(val)
    if vtxt is None:
        continue
    r=int(''.join(ch for ch in coord if ch.isdigit()))
    row_el=rows_by_r.get(r)
    if row_el is None:
        continue
    c_el=find_cell(row_el, coord)
    if c_el is None:
        continue
    # ensure numeric type
    c_el.attrib.pop('t', None)
    v_el=c_el.find(f'{{{sheet_ns}}}v')
    if v_el is None:
        f_el=c_el.find(f'{{{sheet_ns}}}f')
        v_el=ET.Element(f'{{{sheet_ns}}}v')
        v_el.text=vtxt
        if f_el is None:
            c_el.append(v_el)
        else:
            children=list(c_el)
            idx=children.index(f_el)
            c_el.insert(idx+1, v_el)
    else:
        v_el.text=vtxt
    patched += 1

# rewrite xlsx

tmp='/root/output/_tmp.xlsx'
with zipfile.ZipFile(out_path,'r') as zin, zipfile.ZipFile(tmp,'w',compression=zipfile.ZIP_DEFLATED) as zout:
    for item in zin.infolist():
        data=zin.read(item.filename)
        if item.filename==sheet_path:
            data=ET.tostring(root, encoding='utf-8', xml_declaration=True)
        zout.writestr(item, data)

os.replace(tmp, out_path)
print('Patched', patched, 'cells in', sheet_path)

PY

